<?php require 'config.php';require_login();$title='Tasks';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['delete']))$pdo->prepare('DELETE FROM tasks WHERE id=?')->execute([(int)$_POST['delete']]);else $pdo->prepare('INSERT INTO tasks(title,assigned_to,due_date,status) VALUES(?,?,?,?)')->execute([trim($_POST['title']),trim($_POST['assigned_to']),$_POST['due_date']?:null,$_POST['status']]);flash('Task list updated.');go('tasks.php');}
$rows=$pdo->query('SELECT * FROM tasks ORDER BY id DESC')->fetchAll();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">WORK TRACKER</div><h1>Tasks</h1><p class="sub">Keep track of office activities and assignments.</p></div></div>
<div class="card"><h2>Create a task</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid" style="margin-top:15px"><div class="field"><label>Task title</label><input name="title" required></div><div class="field"><label>Assigned to</label><input name="assigned_to" placeholder="Employee name"></div><div class="field"><label>Due date</label><input type="date" name="due_date"></div><div class="field"><label>Status</label><select name="status"><option>Pending</option><option>In Progress</option><option>Completed</option></select></div></div><div class="actions"><button class="btn">＋ Add task</button></div></form></div>
<div class="card"><div class="cardhead"><h2>Task board</h2></div><div class="tablewrap"><table><thead><tr><th>Task</th><th>Assigned to</th><th>Due date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=h($r['title'])?></strong></td><td><?=h($r['assigned_to'])?></td><td><?=h($r['due_date'])?></td><td><span class="badge <?=$r['status']==='Completed'?'':($r['status']==='Pending'?'warn':'')?>"><?=h($r['status'])?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="btn danger small" name="delete" value="<?=$r['id']?>">Delete</button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="5" class="empty">No tasks yet.</td></tr><?php endif?></tbody></table></div></div><?php require 'partials/footer.php';?>
